/* The version script. TODO/interpose.md T-0701 constraint 1.
 *
 * ⛔ A default Rust cdylib exports `rust_eh_personality` and the rest of its
 * runtime into every process it is loaded into, and this object is loaded into
 * every process of a container. What is global here is exactly the set of libc
 * entry points podbox interposes; everything else is local.
 *
 * ⚠ The list is the same one `src/lib.rs` exports with `#[no_mangle]`, and
 * `experiments/105-interpose-ownership.sh` check A asserts the two agree: a
 * symbol in one and not the other is either a silent non-interposition or a
 * symbol some other library in the payload's process resolves to podbox.
 * T-0703 owns the path half of the list; T-0704 the ownership half.
 */
{
  global:
    chown;
    lchown;
    fchown;
    fchownat;
    stat;
    lstat;
    fstat;
    fstatat;
    stat64;
    lstat64;
    fstat64;
    fstatat64;
    __xstat;
    __lxstat;
    __fxstat;
    __fxstatat;
    __xstat64;
    __lxstat64;
    __fxstatat64;
    statx;
    open;
    open64;
    openat;
    openat64;
    openat2;
    creat;
    creat64;
    execve;
    execv;
    execvp;
    execvpe;
    execveat;
    posix_spawn;
    posix_spawnp;
    chdir;
    getcwd;
    get_current_dir_name;
    opendir;
    scandir;
    readlink;
    readlinkat;
    realpath;
    canonicalize_file_name;
    getxattr;
    lgetxattr;
    setxattr;
    lsetxattr;
    listxattr;
    llistxattr;
    removexattr;
    lremovexattr;
    link;
    linkat;
    symlink;
    symlinkat;
    unlink;
    unlinkat;
    rename;
    renameat;
    renameat2;
    mkdir;
    mkdirat;
    rmdir;
    mknod;
    __xmknod;
    mount;
    unshare;
    clone;
    mkstemp;
    mkostemp;
    mkdtemp;
    access;
    eaccess;
    euidaccess;
    faccessat;
    chmod;
    fchmodat;
    truncate;
    utime;
    utimes;
    utimensat;
    statfs;
    statvfs;
    remove;
    fopen;
    fopen64;
    freopen;
    freopen64;
    tmpfile;
    tmpfile64;
    glob;
    glob64;
    ftw;
    ftw64;
    nftw;
    nftw64;
    setuid;
    setgid;
    seteuid;
    setegid;
    setreuid;
    setregid;
    setresuid;
    setresgid;
    setgroups;
    getuid;
    geteuid;
    getgid;
    getegid;
    getgroups;
    getresuid;
    getresgid;
  local:
    *;
};
